import asyncio
import functools
import pytest
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

# Helper to wrap a function multiple times
def complex_wrap(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return functools.partial(wrapper)

async def async_func():
    return "async"

def sync_func():
    return "sync"

async def async_gen():
    yield "async_gen"

def sync_gen():
    yield "sync_gen"

class AsyncCallable:
    async def __call__(self):
        return "async_callable"

class SyncCallable:
    def __call__(self):
        return "sync_callable"

def test_async_path_operation():
    app = FastAPI()

    @app.get("/async")
    @complex_wrap(async_func)
    async def root():
        return {"message": "hello"}

    # The above is slightly wrong because @complex_wrap(async_func) returns a partial, 
    # but the decorator is applied to 'root'.
    # Let's use a more direct approach for path operations.

