    final_dep = functools.partial(wrapper)

    @app.get("/dep")
    async def root(val: str = Depends(final_dep)):
        return {"val": val}

    client = TestClient(app)
    response = client.get("/dep")
    assert response.status_code == 200
    assert response.json() == {"val": "async"}

